compose:
services:
  duplicati:
    image: lscr.io/linuxserver/duplicati:latest
    restart: unless-stopped
    ports:
      - "${PORT_WEB}:8200"
    environment:
      - PUID=${PUID}
      - PGID=${PGID}
      - TZ=${ZEITZONE}
      - SETTINGS_ENCRYPTION_KEY=${SCHLUESSEL}
      - DUPLICATI__WEBSERVICE_PASSWORD=${WEB_PASSWORT}
    volumes:
      - "${PFAD_KONFIG}:/config"
      - "${PFAD_ZIELE}:/backups"
      - "${PFAD_QUELLE}:/source"
